"""Settings content with explicit labels and separate preference sections."""

SETTINGS_CONTENT = r'''<main class="settings-main">
<div class="settings-heading"><div class="section-title">YOUR PANEL</div><h1>Settings</h1><p class="muted">Manage appearance, access, uploads, and Telegram.</p></div>
{% if saved %}<div class="notice" role="status">Settings saved.</div>{% elif error %}<div class="notice" role="alert">{% if error == 'current' %}Current password is incorrect.{% elif error == 'new' %}New passwords must match and contain at least 12 characters.{% elif error == 'message-limit' %}Choose a size between 1 and {{ max_limit_mb }} MB.{% else %}Please check the setting and try again.{% endif %}</div>{% endif %}
<div class="settings-grid">
<section class="form-card settings-card"><div class="settings-card-heading"><span class="settings-symbol" aria-hidden="true">◐</span><div><h2>Appearance</h2><p class="muted">Choose how Relay looks in this browser.</p></div></div><div class="preference-row"><div><strong>Panel theme</strong><p class="hint" id="theme-description">Dark or light appearance.</p></div><button class="theme" id="theme-toggle" type="button" aria-label="Switch panel theme">Switch theme</button></div></section>
<section class="form-card settings-card"><div class="settings-card-heading"><span class="settings-symbol" aria-hidden="true">↥</span><div><h2>Upload limit</h2><p class="muted">Maximum combined text and files per message.</p></div></div><form method="post" action="/settings/message-limit"><input type="hidden" name="csrf" value="{{ csrf }}"><label class="settings-label" for="message-limit">Maximum size</label><div class="settings-input-row"><div class="size-input"><input class="text-input" id="message-limit" type="number" name="limit" min="1" max="{{ max_limit_mb }}" value="{{ message_mb }}" required><span>MB</span></div><button class="button primary" type="submit">Save limit</button></div><p class="hint">Current limit: {{ message_mb }} MB · allowed range: 1–{{ max_limit_mb }} MB.</p></form></section>
<section class="form-card settings-card"><div class="settings-card-heading"><span class="settings-symbol" aria-hidden="true">⌑</span><div><h2>Panel password</h2><p class="muted">Update the password used to sign in.</p></div></div><form class="settings-form" method="post" action="/settings/password"><input type="hidden" name="csrf" value="{{ csrf }}"><label for="current-password">Current password<input class="text-input" id="current-password" name="current" type="password" autocomplete="current-password" required></label><div class="settings-password-row"><label for="new-password">New password<input class="text-input" id="new-password" name="new" type="password" minlength="12" autocomplete="new-password" required></label><label for="confirm-password">Confirm password<input class="text-input" id="confirm-password" name="confirm" type="password" minlength="12" autocomplete="new-password" required></label></div><p class="hint">Use at least 12 characters.</p><button class="button primary" type="submit">Update password</button></form></section>
<section class="form-card settings-card"><div class="settings-card-heading"><span class="settings-symbol" aria-hidden="true">↗</span><div><h2>Telegram</h2><p class="muted">New user alerts and message backups.</p></div></div><span class="integration-status">{% if telegram_configured %}Connected · chat {{ telegram_chat_id }}{% else %}Not configured{% endif %}</span>
{% if telegram_status == 'saved' %}<div class="notice" role="status">Telegram settings saved.</div>{% elif telegram_status == 'disabled' %}<div class="notice">Telegram integration disabled.</div>{% elif telegram_status == 'tested' %}<div class="notice" role="status">Test message sent successfully.</div>{% elif telegram_status == 'missing' %}<div class="notice">Save a token and chat ID first.</div>{% elif telegram_status == 'invalid' %}<div class="notice" role="alert">Enter a valid bot token and chat ID.</div>{% elif telegram_error %}<div class="notice" role="alert">Test failed: {{ telegram_error }}</div>{% endif %}
<form class="settings-form" method="post" action="/settings/telegram"><input type="hidden" name="csrf" value="{{ csrf }}"><label for="bot-token">Bot token<input class="text-input" id="bot-token" type="password" name="bot_token" autocomplete="new-password" placeholder="{% if telegram_configured %}Leave blank to keep the saved token{% else %}Enter your bot token{% endif %}"></label><label for="telegram-chat">Destination chat ID<input class="text-input" id="telegram-chat" name="chat_id" value="{{ telegram_chat_id }}" placeholder="Enter a chat ID" autocomplete="off"></label><button class="button primary" type="submit">Save Telegram</button></form><form method="post" action="/settings/telegram/test" class="telegram-test"><input type="hidden" name="csrf" value="{{ csrf }}"><button class="button" type="submit" {% if not telegram_configured %}disabled{% endif %}>Send a test message</button></form><p class="hint">The saved token stays hidden. Clear the token and chat ID to disable Telegram.</p></section>
</div><section class="form-card session-card"><div><h2>Sign out</h2><p class="muted">End your current panel session.</p></div><form method="post" action="/logout"><input type="hidden" name="csrf" value="{{ csrf }}"><button class="delete" type="submit">Sign out</button></form></section></main>'''


def redesign_settings(source):
    import re
    from feature_ui import STORAGE_CARD
    content = SETTINGS_CONTENT.replace('</div><section class="form-card session-card">', STORAGE_CARD+'</div><section class="form-card session-card">')
    return re.sub(r'<main>.*?</main>', lambda _: content, source, count=1, flags=re.S)
